export const grade8Lessons = baseGrade8Lessons.map((lesson) => ({
  ...lesson,
  ...(interactiveEnhancements[lesson.id] || {}),
}))

export function getGrade8Lesson(id) {
  return grade8Lessons.find((lesson) => lesson.id === id) || null
}

export function getGrade8ChapterLessons(chapterId) {
  return grade8Lessons.filter((lesson) => lesson.chapter === chapterId)
}
